import type { Metadata } from 'next';

import { SITE_NAME } from '@/utils/constants';

type OpenGraph = NonNullable<Metadata['openGraph']>;

/** Generated by `src/app/opengraph-image.tsx`; resolved against `metadataBase`. */
export const DEFAULT_OG_IMAGE_PATH = '/opengraph-image';

export const DEFAULT_OG_IMAGE = {
  url: DEFAULT_OG_IMAGE_PATH,
  width: 1200,
  height: 630,
  type: 'image/png',
  alt: 'Brandon Sauceda, independent software engineer — saucy.tech',
} as const;

/**
 * Next.js replaces a parent segment's `openGraph` object wholesale instead of
 * merging it, so a page that sets only `openGraph.url` silently drops the
 * layout's type, site name, locale and image. Build every `openGraph` block
 * through this helper so those site-wide fields survive; anything passed in
 * (including `type` or `images`) still wins.
 */
export function siteOpenGraph(overrides: OpenGraph = {}): OpenGraph {
  return {
    type: 'website',
    locale: 'en_US',
    siteName: SITE_NAME,
    images: [DEFAULT_OG_IMAGE],
    ...overrides,
  } as OpenGraph;
}
